style.css:
@-moz-document domain("youtube.com") {
/* BACKGROUND PHOTO ONLY */
html,
body,
ytd-app {
    background-image:
    url("https://i.pinimg.com/736x/bb/21/80/bb218031407a03503b0607cc98163a4f.jpg") !important;

    background-size: cover !important;
    background-position: center !important;
    background-attachment: fixed !important;
    background-repeat: no-repeat !important;
}


/* REMOVE YOUTUBE DEFAULT BACKGROUND */
#page-manager,
#content,
ytd-browse,
ytd-watch-flexy {
    background: transparent !important;
}


/* TOP BAR */
#masthead {

    background:
    linear-gradient(
        90deg,
        rgba(255,220,235,.90),
        rgba(215,240,255,.90)
    ) !important;

    backdrop-filter: blur(15px);
}


/* SIDE MENU */
#guide-content,
tp-yt-app-drawer {

    background:
    linear-gradient(
        180deg,
        #ffe2ef,
        #dff5ff
    ) !important;
}


/* VIDEO CARDS */
ytd-rich-item-renderer,
ytd-video-renderer,
ytd-grid-video-renderer {

    background:
    linear-gradient(
        135deg,
        rgba(255,225,240,.85),
        rgba(220,245,255,.85)
    ) !important;

    border-radius: 18px !important;

    backdrop-filter: blur(8px);

    box-shadow:
    0 5px 20px rgba(255,160,200,.25);
}


/* TEXT */
#video-title,
yt-formatted-string,
a,
#channel-name,
#owner-name {

    color: #c85b8c !important;
}


/* SEARCH BAR */
#search-input {

    background: #fff8fc !important;

    border: 2px solid #f5b7d2 !important;

    border-radius: 30px !important;
}


/* BUTTONS */
button {

    color: #c85b8c !important;

    border-radius: 30px !important;
}


/* GLOWING PINK PROGRESS BAR */
.ytp-play-progress {

    background: #ff69b4 !important;

    box-shadow:
    0 0 8px #ff69b4,
    0 0 18px #ff1493,
    0 0 30px #ff69b4 !important;
}


/* PROGRESS BUTTON */
.ytp-scrubber-button {

    background: white !important;

    border: 3px solid #ff69b4 !important;

    box-shadow:
    0 0 12px #ff69b4 !important;
}


/* SCROLL BAR */
::-webkit-scrollbar {

    width: 10px;
}


::-webkit-scrollbar-thumb {

    background:
    linear-gradient(
        #ffb6d6,
        #a9e4ff
    );

    border-radius: 20px;
}
}
